class CustomStack {
    private int[] stack;
    private int[] inc;
    private int top;

    public CustomStack(int maxSize) {
        stack = new int[maxSize];
        inc = new int[maxSize];
        top = -1;
    }

    public void push(int x) {
        if (top + 1 < stack.length) {
            stack[++top] = x;
        }
    }

    public int pop() {
        if (top < 0) {
            return -1;
        }
        int answer = stack[top] + inc[top];
        if (top > 0) {
            inc[top - 1] += inc[top];
        }
        inc[top] = 0;
        top--;
        return answer;
    }

    public void increment(int k, int val) {
        int index = Math.min(k - 1, top);
        if (index >= 0) {
            inc[index] += val;
        }
    }
}

class CustomStack {
    private int[] stack;
    private int size;

    public CustomStack(int maxSize) {
        stack = new int[maxSize];
        size = 0;
    }

    public void push(int x) {
        if (size < stack.length) {
            stack[size++] = x;
        }
    }

    public int pop() {
        if (size == 0) {
            return -1;
        }
        return stack[--size];
    }

    public void increment(int k, int val) {
        int limit = Math.min(k, size);
        for (int i = 0; i < limit; i++) {
            stack[i] += val;
        }
    }
}

import java.util.LinkedList;
import java.util.ListIterator;

class CustomStack {
    private int maxSize;
    private LinkedList<Integer> values;

    public CustomStack(int maxSize) {
        this.maxSize = maxSize;
        values = new LinkedList<>();
    }

    public void push(int x) {
        if (values.size() < maxSize) {
            values.addLast(x);
        }
    }

    public int pop() {
        if (values.isEmpty()) {
            return -1;
        }
        return values.removeLast();
    }

    public void increment(int k, int val) {
        ListIterator<Integer> iterator = values.listIterator();
        int count = 0;
        while (iterator.hasNext() && count < k) {
            iterator.set(iterator.next() + val);
            count++;
        }
    }
}

class CustomStack {
    private int[] values;
    private int[] bit;
    private int size;

    public CustomStack(int maxSize) {
        values = new int[maxSize];
        bit = new int[maxSize + 2];
        size = 0;
    }

    public void push(int x) {
        if (size < values.length) {
            values[size++] = x;
        }
    }

    public int pop() {
        if (size == 0) {
            return -1;
        }
        int index = --size;
        int extra = pointQuery(index);
        rangeAdd(index, index, -extra);
        return values[index] + extra;
    }

    public void increment(int k, int val) {
        int limit = Math.min(k, size);
        if (limit > 0) {
            rangeAdd(0, limit - 1, val);
        }
    }

    private void rangeAdd(int left, int right, int delta) {
        add(left, delta);
        add(right + 1, -delta);
    }

    private void add(int index, int delta) {
        for (int i = index + 1; i < bit.length; i += i & -i) {
            bit[i] += delta;
        }
    }

    private int pointQuery(int index) {
        int sum = 0;
        for (int i = index + 1; i > 0; i -= i & -i) {
            sum += bit[i];
        }
        return sum;
    }
}

class CustomStack {
    private int[] values;
    private int[] lazy;
    private int size;

    public CustomStack(int maxSize) {
        values = new int[maxSize];
        lazy = new int[maxSize * 4 + 4];
        size = 0;
    }

    public void push(int x) {
        if (size < values.length) {
            values[size++] = x;
        }
    }

    public int pop() {
        if (size == 0) {
            return -1;
        }
        int index = --size;
        int extra = query(1, 0, values.length - 1, index);
        add(1, 0, values.length - 1, index, index, -extra);
        return values[index] + extra;
    }

    public void increment(int k, int val) {
        int limit = Math.min(k, size);
        if (limit > 0) {
            add(1, 0, values.length - 1, 0, limit - 1, val);
        }
    }

    private void add(int node, int left, int right, int ql, int qr, int delta) {
        if (qr < left || right < ql) {
            return;
        }
        if (ql <= left && right <= qr) {
            lazy[node] += delta;
            return;
        }
        int mid = left + (right - left) / 2;
        add(node * 2, left, mid, ql, qr, delta);
        add(node * 2 + 1, mid + 1, right, ql, qr, delta);
    }

    private int query(int node, int left, int right, int index) {
        if (left == right) {
            return lazy[node];
        }
        int mid = left + (right - left) / 2;
        if (index <= mid) {
            return lazy[node] + query(node * 2, left, mid, index);
        }
        return lazy[node] + query(node * 2 + 1, mid + 1, right, index);
    }
}
